import React, { useState } from "react";
import axios from "axios";

function TeacherDashboard() {
  const teacherId = localStorage.getItem("user_id");

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    subject_code: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...formData,
        teacher_id: parseInt(teacherId)
      };

      const response = await axios.post("http://127.0.0.1:8000/create-course", payload);
      alert(response.data.message);
    } catch (error) {
      console.error(error);
      alert("Course creation failed");
    }
  };

  return (
    <div>
      <h2 style={{ color: "#4a148c" }}>Teacher Dashboard</h2>
      <form onSubmit={handleSubmit} style={{ maxWidth: "500px", display: "grid", gap: "15px" }}>
        <input type="text" name="title" placeholder="Course Title" onChange={handleChange} />
        <input type="text" name="description" placeholder="Course Description" onChange={handleChange} />
        <input type="text" name="subject_code" placeholder="Subject Code" onChange={handleChange} />
        <button type="submit">Add Course</button>
      </form>
    </div>
  );
}

export default TeacherDashboard;
